tasks.solution:
-- 이 제약 비교 실험의 연습용 reservation 표만 다시 만드는 준비예요.
DROP TABLE IF EXISTS reservation;
CREATE TABLE reservation(
    id INT PRIMARY KEY,
    room_id INT NOT NULL,
    slot INT NOT NULL,
    people INT NOT NULL CHECK(people > 0),
    UNIQUE(room_id, slot),
    FOREIGN KEY(room_id) REFERENCES room(id)
);

